fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since arr.len() > 0 by precondition, single element arrays are sorted by definition
    for i in 0..arr.len() - 1 {
        if arr[i] > arr[i + 1] {
            return false;
        }
    }
    true
}